-- Generado por database/importar_ecocrop.py --terreno -- NO editar a mano.
-- Requiere database/migracion_requisitos_terreno.sql y database/migracion_suelo_declarado.sql.
-- Solo actualiza las once columnas de terreno de las filas de EcoCrop existentes; es idempotente.

BEGIN;

CREATE TEMP TABLE _ecocrop_terreno (
  especie VARCHAR PRIMARY KEY,
  altitud_max_m INT,
  textura_opt TEXT[],
  textura_rango TEXT[],
  drenaje_opt TEXT[],
  drenaje_rango TEXT[],
  salinidad_opt VARCHAR,
  salinidad_max VARCHAR,
  profundidad_opt VARCHAR,
  profundidad_min VARCHAR,
  fertilidad_opt VARCHAR,
  fertilidad_min VARCHAR
) ON COMMIT DROP;


UPDATE requisitos_especie r SET altitud_max_m = e.altitud_max_m, textura_opt = e.textura_opt, textura_rango = e.textura_rango, drenaje_opt = e.drenaje_opt, drenaje_rango = e.drenaje_rango, salinidad_opt = e.salinidad_opt, salinidad_max = e.salinidad_max, profundidad_opt = e.profundidad_opt, profundidad_min = e.profundidad_min, fertilidad_opt = e.fertilidad_opt, fertilidad_min = e.fertilidad_min
FROM _ecocrop_terreno e
WHERE r.especie = e.especie AND r.variedad_local IS NULL AND r.fuente = 'FAO_EcoCrop_opinion_experta';

COMMIT;
